import json

def parse_records(text):
    rows = []
    for number, line in enumerate(filter(None, text.splitlines()), 1):
        try:
            rows.append(json.loads(line))
        except ValueError:
            continue
    return rows

cases.public_check:
from records import parse_records
assert parse_records('{"x": 1}\n\n{"x": 2}\n') == [{'x': 1}, {'x': 2}]
try:
    parse_records('{}\n[1]')
except ValueError as exc:
    assert str(exc) == 'line 2: expected JSON object'
else:
    raise AssertionError('non-object accepted')

cases.heldout_assert_script:
from records import parse_records
assert parse_records('') == []
assert parse_records(' \r\n\t\r\n') == []
assert parse_records(' \r\n{"nested": [null, {"s": "雪"}]}\r\n\t\r\n{}') == [{'nested': [None, {'s': '雪'}]}, {}]
for bad in ['null', 'true', '0', '"text"', '[]', '{', '{} trailing']:
    for prefix, expected_line in [('', 1), ('\n \n{}\n\t\n', 5)]:
        try:
            parse_records(prefix + bad + '\n{}')
        except ValueError as exc:
            assert str(exc) == f'line {expected_line}: expected JSON object', (bad, str(exc))
        else:
            raise AssertionError(('accepted bad record', bad))
try:
    parse_records('{}\n\nnope\n[]')
except ValueError as exc:
    assert str(exc) == 'line 3: expected JSON object'
else:
    raise AssertionError('ignored first error')

