def apply_batch(state, events):
    for event in events:
        account = event['account']
        state['balances'][account] = state['balances'].get(account, 0) + event['delta']
        state['seen'].add(event['id'])
    return state

cases.public_check:
from ledger import apply_batch
from report import summarize
state = {'balances': {'bob': 0}, 'seen': set()}
event = {'id': 'e1', 'account': 'amy', 'delta': 5}
assert apply_batch(state, [event, event]) is state
assert state == {'balances': {'bob': 0, 'amy': 5}, 'seen': {'e1'}}
assert summarize(state) == [('amy', 5)]

